<?php include __DIR__.'/start.php';?><section><p><a href="/admin/manor"><?=me(__('manor.management_console'))?></a></p><p><a class="button" href="/admin/manor/scanner"><?=me(__('manor.scan_attendance'))?></a></p><h1><?=me(__('manor.invitations_attendance'))?></h1>
<form method="get"><label><?=me(__('manor.confirmed_booking'))?><select name="request_id"><?php foreach($bookings as $b):?><option value="<?=me($b['id'])?>" <?=($record['id']??'')===$b['id']?'selected':''?>><?=me($b['name'].' · '.$b['id'])?></option><?php endforeach?></select></label><button><?=me(__('manor.open_guest_list'))?></button></form>
<?php if($record):?><h2><?=me($record['unit_name'])?></h2><?php if($report):?><p><?=me(__('manor.attendance_totals'))?>: <?=me($report['attended'])?> / <?=me($report['total'])?> · RSVP <?=me($report['accepted'])?> / <?=me($report['declined'])?></p><a href="/admin/manor/attendance.csv?request_id=<?=me($record['id'])?>"><?=me(__('manor.export_attendance'))?></a><?php endif?>
<div class="table-scroll"><table><thead><tr><th><?=me(__('manor.guest_name'))?></th><th>RSVP</th><th><?=me(__('manor.attendance'))?></th><th><?=me(__('manor.actions'))?></th></tr></thead><tbody><?php foreach($guests as $g):$links=\App\Manor\Invitations::links($g);?><tr><td><?=me($g['name'])?><br><?=me($g['email'])?></td><td><?=me(__('manor.rsvp_'.$g['rsvp']))?></td><td><?=me($g['checked_at']?:'—')?></td><td><?php if(!$g['revoked_at']):?><a href="<?=me($links['invitation'])?>"><?=me(__('manor.preview_invitation'))?></a><label><?=me(__('manor.shareable_link'))?><input readonly value="<?=me($links['invitation'])?>"></label><form method="post"><?=csrf()?><input type="hidden" name="guest_id" value="<?=me($g['id'])?>"><input type="hidden" name="request_id" value="<?=me($record['id'])?>"><button name="action" value="send"><?=me(__('manor.email_invitation'))?></button><button name="action" value="revoke"><?=me(__('manor.revoke_invitation'))?></button></form><?php if($settings['flags']['qr_attendance']):?><form method="post"><?=csrf()?><input type="hidden" name="action" value="attendance"><input type="hidden" name="guest_id" value="<?=me($g['id'])?>"><input type="hidden" name="request_id" value="<?=me($record['id'])?>"><?=field('reason',__('manor.manual_override_reason'))?><label class="check"><input type="checkbox" name="undo" value="1"><?=me(__('manor.remove_attendance'))?></label><button><?=me(__('manor.apply_manual_attendance'))?></button></form><?php endif?><?php else:?><?=me(__('manor.revoked'))?><?php endif?></td></tr><?php endforeach?></tbody></table></div>
<details><summary><?=me(__('manor.add_guest'))?></summary><form method="post"><?=csrf()?><input type="hidden" name="action" value="invite"><input type="hidden" name="request_id" value="<?=me($record['id'])?>"><?=field('guest_name',__('manor.guest_name'))?><?=field('guest_email',__('manor.guest_email'),'','email',false)?><?=field('event_name',__('manor.event_name'))?><?=field('host_name',__('manor.host_name'))?><?=field('venue_label',__('manor.venue'),$record['unit_name'])?><label><?=me(__('manor.invitation_template'))?><select name="template_id"><?php foreach($templates as $t):if(!$t['enabled'])continue;?><option value="<?=me($t['id'])?>"><?=me($t['name'])?></option><?php endforeach?></select></label><label class="check"><input type="checkbox" name="send" value="1"><?=me(__('manor.send_invitation_now'))?></label><button><?=me(__('manor.create_invitation'))?></button></form></details><?php endif?>
<h2><?=me(__('manor.invitation_templates'))?></h2><?php foreach(array_merge([null],$templates) as $t):$d=$t?json_decode($t['data'],true):[];?><details><summary><?=me($t['name']??__('manor.new_template'))?></summary><form method="post"><?=csrf()?><input type="hidden" name="action" value="template"><input type="hidden" name="template_id" value="<?=me($t['id']??'')?>"><?=field('name',__('manor.template_name'),$t['name']??'')?><label><?=me(__('manor.template_style'))?><select name="style"><?php foreach(['heritage','garden','modern'] as $style):?><option value="<?=$style?>" <?=($t['style']??'')===$style?'selected':''?>><?=me(__('manor.invitation_style_'.$style))?></option><?php endforeach?></select></label><?php foreach(['heading','message','footer','heading_ar','message_ar','footer_ar'] as $key):?><?=field($key,__('manor.'.$key),$d[$key]??'')?><?php endforeach?><?=field('accent',__('manor.accent_color'),$d['accent']??'#b45d32','color')?><?=field('background',__('manor.background_color'),$d['background']??'#fffaf0','color')?><label class="check"><input type="checkbox" name="enabled" value="1" <?=!$t||$t['enabled']?'checked':''?>><?=me(__('manor.enabled'))?></label><button><?=me(__('manor.save_template'))?></button></form></details><?php endforeach?></section><?php include __DIR__.'/end.php';?>
